(() => {
  const sourceTitle = "AP Latin Course and Exam Description (effective Fall 2025)";
  const sourceUrl = "https://apcentral.collegeboard.org/media/pdf/ap-latin-course-and-exam-description.pdf";

  const makeUnit = (number, title, entries, prompts) => {
    const id = `aplatin-unit-${number}`;
    return {
      id,
      name: `Unit ${number}: ${title}`,
      description: `${entries.length} focused cards aligned to the current AP Latin framework.`,
      sourceTitle,
      sourceUrl,
      cards: entries.map(([front, back], index) => ({
        id: `${id}-c${index + 1}`,
        front,
        back,
      })),
      questions: [],
      feynmanPrompts: prompts.map((prompt, index) => ({ id: `${id}-f${index + 1}`, prompt })),
    };
  };

  window.AP_LATIN_DECKS = [
    makeUnit(1, "Teacher’s Choice — Latin Prose", [
      ["Principal parts", "The forms used to derive a Latin verb’s stems: first-person present, present infinitive, first-person perfect, and perfect passive participle."],
      ["Indirect statement", "A reported statement using an accusative subject and infinitive; its infinitive shows time relative to the main verb."],
      ["Sequence of tenses", "The relationship between the tense of a main verb and the allowable tenses of a dependent subjunctive."],
      ["Purpose clause", "A subjunctive clause expressing intention, normally introduced by ut or nē."],
      ["Result clause", "A subjunctive clause expressing an outcome, commonly introduced by ut or ut nōn and anticipated by words such as tam, ita, or tantus."],
      ["Indirect question", "A reported question introduced by an interrogative word and using the subjunctive."],
      ["Fear clause", "A subjunctive clause after a verb of fearing; nē means ‘that,’ while ut means ‘that … not.’"],
      ["Relative clause", "A clause introduced by a relative pronoun whose gender and number follow its antecedent but whose case follows its own role."],
      ["Ablative absolute", "A noun or pronoun plus a participle in the ablative, grammatically detached from the main clause and often translated with ‘when,’ ‘because,’ or ‘although.’"],
      ["Gerund", "A verbal noun, active in meaning, used only in singular oblique cases."],
      ["Gerundive", "A verbal adjective, passive in meaning; with a form of sum it can express necessity or obligation."],
      ["Passive periphrastic", "A gerundive plus sum expressing what must be done; the agent is normally in the dative."],
      ["Deponent verb", "A verb with passive forms but active meaning, such as sequor, sequī, secūtus sum."],
      ["Participle", "A verbal adjective that conveys voice and relative time while agreeing with a noun in gender, number, and case."],
      ["Historical present", "Use of a present-tense verb for a past event to make narration more immediate or vivid."],
      ["Dative of possession", "A dative used with sum to identify the possessor; translate naturally with ‘have.’"],
      ["Ablative of agent", "The person performing a passive action, normally introduced by ā or ab."],
      ["Ablative of means", "The instrument or means by which an action occurs, normally without a preposition."],
      ["Substantive adjective", "An adjective used as a noun because the person or thing it modifies is understood from context."],
      ["Prose word order", "Latin endings signal syntax, so authors can vary word order for emphasis; identify forms and clause boundaries before translating."],
    ], [
      "Explain how to parse a long Latin prose sentence before translating it.",
      "Explain how to distinguish purpose, result, indirect-question, and fear clauses.",
      "Explain how participles and an ablative absolute compress information into a sentence.",
    ]),

    makeUnit(2, "Pliny and the Eruption of Vesuvius", [
      ["Pliny the Younger", "Roman senator and letter writer who gives an eyewitness account of the eruption and narrates his uncle’s death in Letters 6.16 and 6.20."],
      ["Pliny the Elder", "Author, natural philosopher, and fleet commander whose curiosity and rescue mission led him toward Vesuvius during the eruption."],
      ["Tacitus", "Historian to whom Pliny addresses Letters 6.16 and 6.20, framing the account as material for history."],
      ["Misenum", "Naval base across the Bay of Naples where the Younger Pliny and his uncle were stationed when the eruption began."],
      ["Stabiae", "Coastal location where Pliny the Elder sheltered with Pomponianus and died during the eruption."],
      ["Rectina", "Woman whose plea for rescue helps turn Pliny the Elder’s scientific expedition into a humanitarian mission."],
      ["Pomponianus", "Friend whom Pliny the Elder reassures at Stabiae while the disaster intensifies."],
      ["Epistolography", "The composition of letters as a literary form; Pliny shapes recipients, details, pacing, and persona for an audience beyond the addressee."],
      ["Eyewitness narrative", "An account presented by someone who observed events; evaluate what the narrator directly saw versus learned from others."],
      ["nūbēs", "Cloud; Pliny famously compares the eruption cloud’s shape to a pine tree."],
      ["cinis", "Ash, a recurring physical danger in the eruption narrative."],
      ["pūmex", "Pumice stone; falling stones and ash reveal the eruption’s escalating danger."],
      ["tremor", "A shaking or earthquake, central to Pliny the Younger’s experience at Misenum."],
      ["lītus", "Shore or coastline, important to the attempted sea evacuation and rescue."],
      ["classis", "Fleet; Pliny the Elder commanded the Roman fleet at Misenum."],
      ["fortūna", "Chance, fortune, or fate; context determines whether it means circumstance, luck, or destiny."],
      ["virtūs", "Courage or excellence; Roman virtūs is public character demonstrated through action, not simply modern ‘virtue.’"],
      ["Scientific curiosity and duty", "Pliny presents the Elder’s desire to investigate nature alongside his responsibility to help people in danger."],
      ["Narrative pacing", "Variation in detail, sentence length, and sequence that can slow reflection or accelerate danger."],
      ["Pliny’s authorial persona", "The carefully constructed image of a disciplined, observant, ethical narrator whose choices guide the reader’s judgment."],
    ], [
      "Explain how Pliny turns a private letter about Vesuvius into historical testimony.",
      "Explain how to separate direct observation, reported action, and literary shaping in Letters 6.16 and 6.20.",
      "Explain how Pliny characterizes his uncle through actions rather than a simple list of traits.",
    ]),

    makeUnit(3, "Pliny: Ghosts, Trajan, and Calpurnia", [
      ["Athenodorus", "Philosopher in Pliny’s haunted-house story who follows a chained specter and helps uncover improperly buried remains."],
      ["Pliny, Letter 7.27", "The letter on ghosts and apparitions that tests belief through multiple stories, culminating in Athenodorus and the haunted house."],
      ["Pliny–Trajan correspondence", "Letters in Book 10 that reveal provincial administration through Pliny’s questions and the emperor’s replies."],
      ["Trajan", "Roman emperor whose replies to Pliny emphasize precedent, restraint, and practical administration."],
      ["Roman citizenship", "A legal status carrying privileges and obligations; Pliny asks Trajan to grant it to a physician connected with his household."],
      ["Aqueduct correspondence", "Letters 10.37 and 10.90 show Pliny seeking imperial guidance about costly, unfinished water projects."],
      ["Calpurnia", "Pliny’s wife and addressee of affectionate letters that construct an idealized literary marriage."],
      ["patrōnus and cliēns", "A reciprocal Roman relationship in which a patron offers protection or access and a client provides loyalty and services."],
      ["pietās", "Devotion to family, community, gods, and duty; its meaning depends on the obligations emphasized by a passage."],
      ["dignitās", "Social standing, worth, and public reputation earned and defended through conduct."],
      ["fidēs", "Trust, reliability, loyalty, or good faith in personal and civic relationships."],
      ["ōtium and negōtium", "Leisure devoted to literary or intellectual activity versus public business and official responsibilities."],
      ["exemplum", "A moral or historical example offered as a model, warning, or basis for judgment."],
      ["Epistolary persona", "The identity a letter writer constructs through what is included, omitted, praised, and presented to the recipient."],
      ["Tricolon", "A series of three parallel words, phrases, or clauses used for rhythm and emphasis."],
      ["Asyndeton", "Omission of conjunctions between parallel items, often making expression feel rapid or forceful."],
      ["Polysyndeton", "Deliberate repetition of conjunctions, often slowing the pace or emphasizing accumulation."],
      ["Chiasmus", "An inverted ABBA arrangement of corresponding words or ideas."],
      ["Hyperbaton", "Separation of grammatically connected words, often producing emphasis or enclosing another idea."],
      ["Litotes", "Understatement that affirms an idea by negating its opposite, such as ‘not insignificant.’"],
      ["Antithesis", "A balanced contrast of words or ideas that sharpens a distinction."],
    ], [
      "Explain how Pliny makes the haunted-house story credible while preserving uncertainty.",
      "Explain how the Pliny–Trajan letters reveal both imperial power and the limits of provincial decision-making.",
      "Explain how to connect a prose device such as chiasmus or hyperbaton to meaning instead of merely naming it.",
      "Explain how Pliny constructs different versions of himself for Trajan, Calpurnia, and a literary audience.",
    ]),

    makeUnit(4, "Latin Poetry and Aeneid Books 1–2", [
      ["Dactylic hexameter", "The meter of Latin epic: six feet, usually dactyls or spondees, with a final foot that is normally a spondee or trochee."],
      ["Dactyl", "A metrical foot with one long syllable followed by two short syllables."],
      ["Spondee", "A metrical foot consisting of two long syllables; a run of spondees can make a line feel weighty or slow."],
      ["Caesura", "A meaningful word break within a metrical foot that shapes rhythm and emphasis."],
      ["Elision", "Omission in scansion of a word-final vowel or vowel plus m before a word beginning with a vowel or h."],
      ["Enjambment", "Continuation of a syntactic unit across the end of a poetic line without a strong pause."],
      ["Epic simile", "An extended comparison that temporarily expands beyond the immediate action and invites thematic connections."],
      ["Invocation", "The poet’s appeal to a Muse or divine source for inspiration and authority."],
      ["in mediās rēs", "Beginning a narrative in the middle of the action rather than at its chronological start."],
      ["arma virumque", "‘Arms and the man,’ the opening phrase announcing both warfare and Aeneas as the poem’s subjects."],
      ["Aeneas", "Trojan leader defined by competing obligations to family, followers, gods, and fate."],
      ["Juno", "Goddess whose anger drives much of the poem’s conflict because of her attachments, grievances, and fear for Carthage."],
      ["Dido", "Queen and founder of Carthage, introduced through her capable leadership before her relationship with Aeneas becomes tragic."],
      ["Laocoön", "Trojan priest who warns against the wooden horse and is killed with his sons by serpents."],
      ["Sinon", "Greek agent whose deceptive story persuades the Trojans to bring the wooden horse into the city."],
      ["Trojan Horse", "The Greek stratagem that turns Troy’s apparent victory into destruction after the Trojans admit it within their walls."],
      ["fātum", "Fate or divinely determined course; characters can delay, misunderstand, or resist it but cannot erase it."],
      ["furor", "Uncontrolled passion, rage, or disorder, frequently opposed to duty, restraint, and civic order."],
      ["numen", "Divine will, power, or presence rather than simply a named god."],
      ["Ekphrasis", "A vivid verbal description of a work of art or object that adds narrative and thematic meaning."],
      ["Poetic word order", "Unusual placement or separation of words can imitate action, create suspense, link ideas, or place emphasis at line boundaries."],
    ], [
      "Explain how to scan a line of dactylic hexameter and justify each long syllable.",
      "Explain how Vergil’s meter and word order can reinforce the action of the storm.",
      "Explain how the Laocoön episode creates ambiguity about signs, persuasion, and responsibility.",
      "Explain how to analyze an epic simile beyond identifying its two subjects.",
    ]),

    makeUnit(5, "Aeneid Books 4, 6, 7, 11, and 12", [
      ["Fama", "Rumor personified as a swift, many-eyed monster whose spread turns private events into public and political consequences."],
      ["Mercury’s warning", "Jupiter sends Mercury to remind Aeneas that his divinely assigned future lies in Italy, not Carthage."],
      ["Dido and duty", "The Book 4 conflict pits Dido’s personal and political devastation against Aeneas’s obligation to fate and his people."],
      ["Katabasis", "A hero’s descent into the underworld; Aeneas’s journey gives him knowledge of loss, destiny, and Rome’s future."],
      ["The Sibyl", "Prophetess who guides Aeneas through the underworld after he secures the golden bough."],
      ["Anchises in the underworld", "Aeneas’s father interprets the future Roman lineage and articulates an ideal Roman mission."],
      ["Roman mission", "Anchises describes Roman power as governing peoples, establishing peace, sparing the conquered, and defeating the proud."],
      ["Latinus", "King in Italy who recognizes signs that Lavinia should marry a foreigner but cannot prevent the war that follows."],
      ["Lavinia", "Daughter of Latinus whose marriage is politically central to the conflict between Aeneas and Turnus."],
      ["Turnus", "Rutulian warrior and Aeneas’s chief Italian rival, driven by honor, anger, divine manipulation, and his claim to Lavinia."],
      ["Camilla", "Volscian warrior maiden celebrated for speed and martial skill, whose death shifts the Italian war."],
      ["Juturna", "Turnus’s divine sister, who tries to delay his destined defeat despite knowing the gods’ decision."],
      ["Pallas", "Young ally entrusted to Aeneas whose death at Turnus’s hands becomes decisive in the poem’s ending."],
      ["Pallas’s baldric", "The belt Turnus takes from Pallas; when Aeneas sees it in the final scene, it triggers his lethal response."],
      ["clementia", "Mercy or restraint shown by someone with power; its absence or failure is crucial to interpreting the ending."],
      ["imperium", "Command, political authority, or territorial rule; in epic it connects personal warfare to Rome’s future power."],
      ["pax", "Peace, often presented not as mere absence of conflict but as an order established and enforced by power."],
      ["Augustan context", "The poem emerges after Roman civil wars under Augustus, making its promises of order inseparable from memories of violence."],
      ["Prophecy in the Aeneid", "Forecasts connect Aeneas’s immediate losses to a distant Roman future while raising questions about the cost of destiny."],
      ["The final duel", "Aeneas defeats the wounded Turnus; Turnus appeals for mercy, but the sight of Pallas’s baldric prompts Aeneas to kill him."],
      ["Ambiguity of the ending", "The conclusion can be read as justice, vengeance, surrender to furor, fulfillment of duty, or an intentionally unresolved combination."],
    ], [
      "Explain how to evaluate Aeneas’s decision to leave Dido without reducing either character to a simple hero or villain.",
      "Explain how the underworld episode connects personal memory to Rome’s political future.",
      "Explain how to trace the conflict between pietas and furor across Books 4–12.",
      "Explain how to build two evidence-based interpretations of Aeneas’s final decision about Turnus.",
    ]),

    makeUnit(6, "Course Project and Unseen Latin Poetry", [
      ["Sight reading", "Reading an unfamiliar passage by combining morphology, syntax, vocabulary, genre, and context instead of translating one word at a time."],
      ["Parsing", "Identifying a word’s form and function—for example, a noun’s case or a verb’s person, number, tense, voice, and mood."],
      ["Clause boundary", "The point where one clause begins or ends; finite verbs, conjunctions, relative words, and punctuation help locate it."],
      ["Dictionary headword", "The form under which a word is listed: nominative singular for most nouns, masculine nominative singular for adjectives, and first principal part for verbs."],
      ["Literal translation", "A translation that accurately preserves grammatical relationships before stylistic smoothing."],
      ["Contextual translation", "A fluent rendering that preserves the passage’s meaning, tone, and relationships without ignoring its grammar."],
      ["Scansion workflow", "Mark elisions, identify the fixed ending, locate likely long syllables, divide feet, and then test the rhythm against syntax."],
      ["Tone", "The speaker’s or narrator’s attitude, inferred from diction, imagery, syntax, sound, and context."],
      ["Genre", "A literary category with conventions—such as epic, elegy, lyric, or epistle—that shapes audience expectations."],
      ["Intertextuality", "A text’s meaningful relationship with another text through quotation, echo, structure, character, or theme."],
      ["Textual evidence", "A precise Latin word, phrase, construction, or stylistic feature used to support an interpretation."],
      ["Analytical claim", "A defensible statement about how or why a passage creates meaning, not merely a plot summary or device label."],
      ["Commentary", "Reasoning that connects quoted or cited evidence to a claim and explains the evidence’s significance."],
      ["Point of view", "The position from which events are presented, including what the narrator knows, values, emphasizes, or withholds."],
      ["Diction", "An author’s deliberate word choice and the connotations those words carry in context."],
      ["Imagery", "Language appealing to sensory experience or creating a mental picture, often supporting tone and theme."],
      ["Sound device", "A meaningful pattern such as alliteration, assonance, consonance, or onomatopoeia."],
      ["Theme", "A sustained idea or question developed through the passage, not a one-word topic."],
      ["Passage annotation", "Brief markings that identify verbs, clauses, referents, notable word order, meter, and evidence without obscuring the text."],
      ["Course project", "A sustained investigation using selected Latin passages, contextual research, checkpoints, and evidence-based interpretation."],
    ], [
      "Explain a repeatable process for sight-reading an unfamiliar Latin poem.",
      "Explain how to move from a literal translation to a polished translation without losing grammatical accuracy.",
      "Explain how to turn a noticed stylistic feature into a defensible analytical claim.",
      "Explain how to choose, organize, and cite Latin evidence for a course-project argument.",
    ]),
  ];
})();
